        for quarter in ['Q1', 'Q2', 'Q3', 'Q4']:
            current_sales = quarterly_sales.get(quarter, 0)
            if previous_sales is not None:
                # Calculate percentage increase
                increase_percentage = ((current_sales - previous_sales) / previous_sales) * 100
                # Update max increase if current increase is higher
                if product not in max_increase_product or increase_percentage > max_increase_product[product][0]:
